VALUES (360249, 'tt4738360', NULL, 'The Last King', 'Birkebeinerne', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/vnOirhpqUu9L2hPf9iwmBmQHmtK.jpg', 'https://image.tmdb.org/t/p/original/JbsB9SIefeFo2ko56GflcNqERi.jpg', 'Norway, 1204. A civil war between the birkebeiners —the king''s men— and the baglers —supporters of the Norwegian aristocracy and the Church— ravages the country. Two men must protect a baby, the illegitimate son of King Håkon, who will be the future king and peacemaker, from those who want to kill him.', NULL, NULL, 1.6016, 5.7, 0, 1.04, '2026-11-22 13:01:12', '2026-11-22 13:01:12')
ON CONFLICT(media_type, tmdb_id) WHERE tmdb_id IS NOT NULL DO UPDATE SET "tmdb_id"=excluded."tmdb_id", "imdb_id"=excluded."imdb_id", "igdb_id"=excluded."igdb_id", "title"=excluded."title", "original_title"=excluded."original_title", "media_type"=excluded."media_type", "release_year"=excluded."release_year", "poster_url"=excluded."poster_url", "backdrop_url"=excluded."backdrop_url", "overview"=excluded."overview", "external_url"=excluded."external_url", "platforms"=excluded."platforms", "popularity"=excluded."popularity", "vote_average"=excluded."vote_average", "is_ambiguous"=excluded."is_ambiguous", "evidence_score"=excluded."evidence_score", "updated_at"=excluded."updated_at";
