VALUES (1061859, 'tt28352066', NULL, 'Once Within a Time', 'Once Within a Time', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/lynZTmyyNnL7jfohkerZJvNEXtl.jpg', 'https://image.tmdb.org/t/p/original/2ezdGELR9CoXqnEd4sdH3o3b68h.jpg', 'Once Within a Time is an anarchic comedy told without words, a sensory feast to be felt through art and music. This multidisciplinary work shows us life on Earth as humanity clashes with the five fundamental elements—earth, air, water, fire, and money— headed towards a critical moment of choice between annihilation and redemption.', NULL, NULL, 0.6187, 4.6, 0, 1.01, '2026-11-22 13:01:12', '2026-11-22 13:01:12')
