VALUES (163895, 'tt5864982', NULL, 'P.opular S.ky (section-ish)', 'P.opular S.ky (section-ish)', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/x42tCCvqBocenUNtVcYcq7wR0I4.jpg', 'https://image.tmdb.org/t/p/original/th4dd2ipwhGniY30SAp0Qy7uFHk.jpg', 'In P.opular S.ky (section ish), a character played by Trecartin informs us that she wants ‘to live in a world where narration is the devil’. The ability to script oneself is an inalienable right, and anything that opposes that right must be rejected.', NULL, NULL, 0.5052, 0.0, 0, 1.01, '2026-11-22 13:01:12', '2026-11-22 13:01:12')
