VALUES (38523, 'tt0117359', NULL, 'Ponette', 'Ponette', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/p6ZlnYATJvYZtcQr6RDmzplq3hX.jpg', 'https://image.tmdb.org/t/p/original/jH0AM4Z928cDooUTtIXjXUveGAe.jpg', 'After losing her mother in a car accident that leaves her with a broken arm, 4-year-old Ponette struggles with anguish and fear. Left by her father with a caring aunt and her children, Ponette grieves, secretly hoping her mother will somehow come back. Confused by the religious explanations provided by adults, and challenged by the cruel taunts of a few children at school, little Ponette must make her way through her emotional turmoil.', NULL, NULL, 1.4681, 7.4, 0, 1.01, '2026-11-22 13:01:12', '2026-11-22 13:01:12')
