VALUES (6114, 'tt0103874', NULL, 'Bram Stoker''s Dracula', 'Bram Stoker''s Dracula', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/wpRrdm6g8zWtJnzVqME5QwSKkn7.jpg', 'https://image.tmdb.org/t/p/original/fGuhbAlDpvmNuC0vkz1vsIzYwsq.jpg', 'Count Dracula, a 15th-century prince, is condemned to live off the blood of the living for eternity. Young lawyer Jonathan Harker is sent to Dracula''s castle to finalise a land deal, but when the Count sees a photo of Harker''s fiancée, Mina, the spitting image of his dead wife, he imprisons him and sets off for London to track her down.', NULL, NULL, 10.7092, 7.438, 0, 8.54491358024691436e+01, '2026-07-15 12:01:52', '2026-11-22 13:01:12')
