VALUES (9081, 'tt0243017', NULL, 'Waking Life', 'Waking Life', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/2MRM4PL6H7yraAkwyUEe2EqoQH3.jpg', 'https://image.tmdb.org/t/p/original/56MLZww2dMVAaTt5LDKCBu1do2X.jpg', 'Waking Life is about a young man in a persistent lucid dream-like state. The film follows its protagonist as he initially observes and later participates in philosophical discussions that weave together issues like reality, free will, our relationships with others, and the meaning of life.', NULL, NULL, 3.4398, 7.464, 0, 4.99595555555555534e+01, '2026-07-15 12:01:52', '2026-11-22 13:01:12')
