VALUES (268, 'tt0096895', NULL, 'Batman', 'Batman', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', 'https://image.tmdb.org/t/p/original/rhc7OF7tC9HPu0X8DBKQJzaGRbu.jpg', 'Having witnessed his parents'' brutal murder as a child, millionaire philanthropist Bruce Wayne fights crime in Gotham City disguised as Batman, a costumed hero who strikes fear into the hearts of villains. But when a deformed madman known as ''The Joker'' seizes control of Gotham''s criminal underworld, Batman must face his most ruthless nemesis ever while protecting both his identity and his love interest, reporter Vicki Vale.', NULL, NULL, 10.4865, 7.235, 0, 30.30125, '2026-07-15 12:01:52', '2026-11-22 13:01:12')
