VALUES (12159, 'tt0120889', NULL, 'What Dreams May Come', 'What Dreams May Come', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/78wCdphUzeb528wLZw2W0fn7yGB.jpg', 'https://image.tmdb.org/t/p/original/586n41CjDveXtwmQgP41YtyHKUV.jpg', 'After Chris Nielsen dies in a car accident, he is guided through the afterlife by his spirit guide, Albert. His new world is beautiful and can be whatever Chris imagines. Even his children are there. But, when his wife, Annie, commits suicide and is sent to hell, Chris ignores Albert''s warnings and journeys there to save her. Upon arrival, Chris finds that rescuing Annie will be more difficult than he''d imagined.', NULL, NULL, 5.7958, 7.253, 0, 1.14146999999999991e+02, '2026-07-15 12:01:52', '2026-11-22 13:01:12')
