VALUES (2657, 'tt0120789', NULL, 'Pleasantville', 'Pleasantville', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/sjnRihb0OdmtD5GBe5lfdfBjSxo.jpg', 'https://image.tmdb.org/t/p/original/yPmLNEl9tC9RBO5c95L2R67uxGR.jpg', 'Geeky teenager David and his popular twin sister, Jennifer, get sucked into the black-and-white world of a 1950s TV sitcom called "Pleasantville," and find a world where everything is peachy keen all the time. But when Jennifer''s modern attitude disrupts Pleasantville''s peaceful but boring routine, she literally brings color into its life.', NULL, NULL, 4.2204, 7.269, 0, 4.9272888888888886e+01, '2026-07-20 01:02:04', '2026-11-22 13:01:12')
