VALUES (808, 'tt0126029', NULL, 'Shrek', 'Shrek', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/zscUsmzDJFZjUY8f8BQqMSWlmNQ.jpg', 'https://image.tmdb.org/t/p/original/2Biv1mSzaaxWOqvcnDZn4GcYEAb.jpg', 'It ain''t easy bein'' green -- especially if you''re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.', NULL, NULL, 24.1106, 7.8, 0, 26.845, '2026-07-20 01:02:04', '2026-11-22 13:01:12')
