VALUES (1124566, 'tt27714581', NULL, 'Sentimental Value', 'Affeksjonsverdi', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/AcbS8VMysrTpG9r4dgK1oyLsKYn.jpg', 'https://image.tmdb.org/t/p/original/o6c4TQsnZilCFuQExQuRkF2letr.jpg', 'Sisters Nora and Agnes reunite with their estranged father, the charismatic Gustav, a once-renowned director who offers stage actress Nora a role in what he hopes will be his comeback film. When Nora turns it down, she soon discovers he has given her part to an eager young Hollywood star.', NULL, NULL, 8.0452, 7.5, 0, 8.014, '2026-07-20 04:02:06', '2026-11-22 13:01:12')
