VALUES (608654, 'tt9831136', NULL, 'The Banana Splits Movie', 'The Banana Splits Movie', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/vG9FY2wHVwOOQfqNlUt2LbRzRNl.jpg', 'https://image.tmdb.org/t/p/original/gEeM0ya0UDkdn7EgP5ivabZ754v.jpg', 'A boy named Harley and his family attend a taping of The Banana Splits TV show, which is supposed to be a fun-filled birthday for young Harley and business as usual for Rebecca, the producer of the series. But things take an unexpected turn - and the body count quickly rises. Can Harley, his mom and their new pals safely escape?', NULL, NULL, 3.4347, 6.506, 0, 8.756, '2026-07-20 04:02:06', '2026-11-22 13:01:12')
