VALUES (14353, 'tt0963194', NULL, 'Repo! The Genetic Opera', 'Repo! The Genetic Opera', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/2G5LczM1clXu3byEudWk9w0KDYD.jpg', 'https://image.tmdb.org/t/p/original/xLH9jvY4tNzcKvopgEGYI7YeAy7.jpg', 'By the year 2056, an epidemic of organ failures has devastated the planet. The megacorporation GeneCo provides organ transplants on a payment plan — and those unable to fulfill their plans have their organs repossessed. In the midst of this, a sickly teenager discovers a shocking secret about herself, her father, and their connection to GeneCo.', NULL, NULL, 2.1418, 6.3, 0, 3.8593529411764706e+01, '2026-07-20 04:02:06', '2026-11-22 13:01:12')
