VALUES (36196, 'tt0114095', NULL, 'Party Girl', 'Party Girl', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/cfGEUftQVjvJHTTc3OKbzfsBamT.jpg', 'https://image.tmdb.org/t/p/original/sMiMYF7sf8h6s8R0a3r1bO1Y3Wk.jpg', 'Although Mary has little income, she still finds ways to spend her nights at clubs. After being arrested for throwing an illegal rave, she asks her aunt Judy for bail money. Judy then finds Mary a job at her library so that Mary can repay her. Initially, Mary finds the job as a clerk boring and stifling, and prefers to get to know a street food vendor whom she likes. However, Mary must refocus her life once she loses her job and apartment.', NULL, NULL, 1.748, 6.577, 0, 1.59884615384615393e+01, '2026-07-20 04:02:06', '2026-11-22 13:01:12')
