VALUES (12271, 'tt0432402', NULL, 'Factory Girl', 'Factory Girl', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/A5Sq71054VptVUQYGdIjjim4hFn.jpg', 'https://image.tmdb.org/t/p/original/8eoOLd148gWhboEckk2HyRLZkpG.jpg', 'In the mid-1960s, wealthy debutant Edie Sedgwick meets artist Andy Warhol. She joins Warhol''s famous Factory and becomes his muse. Although she seems to have it all, Edie cannot have the love she craves from Andy, and she has an affair with a charismatic musician, who pushes her to seek independence from the artist and the milieu.', NULL, NULL, 1.8403, 6.0, 0, 8.34, '2026-07-20 04:02:06', '2026-11-22 13:01:12')
