VALUES (433941, 'tt4457344', NULL, 'Dave Made a Maze', 'Dave Made a Maze', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/f2sMi0iBt44E0M5jmSCaOAnGVZp.jpg', 'https://image.tmdb.org/t/p/original/hgg4VH9vtujHTh87wI5KIYNSwPy.jpg', 'Dave, an artist who has yet to complete anything significant in his career, builds a fort in his living room out of pure frustration, only to wind up trapped by the fantastical pitfalls, booby traps, and critters of his own creation. Ignoring his warnings, Dave’s girlfriend Annie leads a band of oddball explorers on a rescue mission. Once inside, they find themselves trapped in an ever-changing supernatural world, threatened by booby traps and pursued by a bloodthirsty Minotaur.', NULL, NULL, 2.2044, 6.409, 0, 2.85991666666666688e+01, '2026-07-21 03:32:24', '2026-11-22 13:01:12')
