VALUES (10588, 'tt0312528', NULL, 'The Cat in the Hat', 'The Cat in the Hat', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/uYYLz67e5xEQMsY858VSSCDsLU6.jpg', 'https://image.tmdb.org/t/p/original/ihOd5W6qOgrBSLj0uDTnGs8k1aa.jpg', 'During a rainy day, and while their mother is out, Conrad and Sally, and their pet fish, are visited by the mischievous Cat in the Hat. Fun soon turns to mayhem, and the siblings must figure out how to rid themselves of the maniacal Cat.', NULL, NULL, 15.3831, 5.401, 0, 32.2325, '2026-07-21 03:32:24', '2026-11-22 13:01:12')
