VALUES (8989, 'tt0093148', NULL, 'Harry and the Hendersons', 'Harry and the Hendersons', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/5ZNWhOEsuNHIQ1gbtwdTGK7srCr.jpg', 'https://image.tmdb.org/t/p/original/4DGZNuxMMcCjVjmn2INTUu66mWX.jpg', 'Returning from a hunting trip in the forest, the Henderson family''s car hits an animal in the road. At first they fear it was a man, but when they examine the "body" they find it''s a "bigfoot". They think it''s dead so they decide to take it home (there could be some money in this). As you guessed, it isn''t dead. Far from being the ferocious monster they fear "Harry" to be, he''s a friendly giant.', NULL, NULL, 7.3102, 6.119, 0, 22.6775, '2026-07-29 20:51:09', '2026-11-22 13:01:12')
