VALUES (198663, 'tt1790864', NULL, 'The Maze Runner', 'The Maze Runner', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/ode14q7WtDugFDp78fo9lCsmay9.jpg', 'https://image.tmdb.org/t/p/original/eTlcNXGv32zkVI7ZDHhfeaKHXKQ.jpg', 'A teenager with no memory of his past finds himself among a group of boys living in a walled enclosure surrounded by a massive, ever-changing maze. As he struggles to adapt to their rules and society, he begins to uncover clues that may lead to escape and the truth behind their confinement.', NULL, NULL, 22.9068, 7.187, 0, 1.06888888888888882e+01, '2026-07-31 03:33:23', '2026-11-22 13:01:12')
