VALUES (8838, 'tt0409630', NULL, 'Texhnolyze', 'TEXHNOLYZE', 'tv', 2003, 'https://image.tmdb.org/t/p/w500/4ZVfHLBx6UMIa6jxWNQ5GcIvqOX.jpg', 'https://image.tmdb.org/t/p/original/2WF4740oFcY5O89K2ktexCfyx9G.jpg', 'Denizens of Lux have come to call it "The City" and treat it as a sentient force. Three factions vie for control of the city: the Organo, a strictly professional conglomerate with ties to the criminal underworld in the prosthetics business; the Union, a fanatical populist group interfering with Organo''s affairs; and Racan, a marauding group of Texhnolyzed youths.', NULL, NULL, 10.0993, 7.0, 0, 5.85, '2026-08-25 01:38:26', '2026-11-22 13:01:12')
