VALUES (10019, 'tt0093493', NULL, 'Mannequin', 'Mannequin', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/oHMA8euTiZdDFXDi5zaIQQXwl0K.jpg', 'https://image.tmdb.org/t/p/original/rbYlmgMV96GcvTe700peiTH5JcS.jpg', 'Jonathan Switcher, an unemployed artist, finds a job as an assistant window dresser for a department store. When Jonathan happens upon a beautiful mannequin he previously designed, she springs to life and introduces herself as Emmy, an Egyptian under an ancient spell. Despite interference from the store''s devious manager, Jonathan and his mannequin fall in love while creating eye-catching window displays to keep the struggling store in business.', NULL, NULL, 10.6953, 6.9, 0, 6.07666666666666621e+00, '2026-10-16 22:59:46', '2026-11-22 13:01:12')
