VALUES (16520, 'tt0049408', NULL, 'The King and I', 'The King and I', 'movie', 1956, 'https://image.tmdb.org/t/p/w500/wUfaP0lLaMpZzp5CrHyII5Vd7cp.jpg', 'https://image.tmdb.org/t/p/original/gjFI54BO9f6eZ2iQyNDhgVVnUCJ.jpg', 'Widowed Welsh mother Anna Leonowens becomes a governess and English tutor to the wives and many children of the stubborn King Mongkut of Siam. Anna and the King have a clash of personalities as she works to teach the royal family about the English language, customs and etiquette, and rushes to prepare a party for a group of European diplomats who must change their opinions about the King.', NULL, NULL, 5.3559, 7.1, 0, 5.5166666666666666e+00, '2026-10-18 12:45:15', '2026-11-22 13:01:12')
